// Chainable no-op — covers most single()/eq()/is()/select() chains
function makeChain(result: unknown = { data: null, error: null }): Record<string, unknown> {
  const chain: Record<string, () => Record<string, unknown>> = {}
  const proxy = new Proxy(chain, {
    get: (_t, prop) => {
      if (prop === 'then') return undefined // not a thenable
      if (prop === 'single' || prop === 'maybeSingle') return async () => result
      return () => proxy
    },
  })
  return proxy
}

